#!/usr/bin/env node
/**
 * Fails when a hand-written page in src/content/docs is longer than the budget.
 *
 *   node scripts/check-length.mjs
 *
 * Generated pages are exempt: they carry the `<!-- Generated by scripts/sync-content.mjs ... -->`
 * marker and exist to be scanned, not read. Everything else is written by hand and has to stay
 * short enough to be useful on a phone.
 */
import { readdir, readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const SITE_ROOT = path.resolve(fileURLToPath(new URL('..', import.meta.url)));
const CONTENT = path.join(SITE_ROOT, 'src', 'content', 'docs');
const GENERATED_MARKER = '<!-- Generated by scripts/sync-content.mjs';
const LIMIT = 900;

async function walk(dir) {
  const files = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...(await walk(full)));
    else if (/\.mdx?$/.test(entry.name)) files.push(full);
  }
  return files;
}

/** `wc -w`: whitespace-separated tokens, over the whole file including frontmatter. */
const words = (text) => text.split(/\s+/).filter(Boolean).length;

const files = (await walk(CONTENT)).sort();
const over = [];
const skipped = [];
const counted = [];

for (const file of files) {
  const text = await readFile(file, 'utf8');
  const relative = path.relative(CONTENT, file);
  if (text.includes(GENERATED_MARKER)) {
    skipped.push(relative);
    continue;
  }
  const count = words(text);
  counted.push({ relative, count });
  if (count > LIMIT) over.push({ relative, count });
}

const largest = counted.sort((a, b) => b.count - a.count).slice(0, 5);
console.log(`Hand-written pages: ${counted.length} (${skipped.length} generated pages skipped)`);
console.log(`Longest hand-written pages: ${largest.map((p) => `${p.relative} ${p.count}`).join(', ')}`);

if (over.length > 0) {
  console.error(`\n${over.length} page(s) over ${LIMIT} words:`);
  for (const page of over) console.error(`  ${page.count}  ${page.relative}`);
  process.exit(1);
}

console.log(`All hand-written pages are within ${LIMIT} words.`);
